import os
import time

SEEN = set()


def new_files(folder):
    found = []
    for root, _dirs, names in os.walk(folder):
        for name in names:
            path = os.path.join(root, name)
            if path not in SEEN:
                SEEN.add(path)
                found.append(path)
    return found


def run(folder, handle, every=60):
    while True:
        for path in new_files(folder):
            handle(path)
        time.sleep(every)
